{
  "findings": [
    {
      "check_id": "CKV_GCP_14",
      "title": "Backup configuration is disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "HIGH",
      "explanation": "Backups are disabled for the database instance, which increases the risk of data loss in case of accidental deletion or corruption."
    },
    {
      "check_id": "CKV_GCP_16",
      "title": "SSL is not required for database connections",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "CRITICAL",
      "explanation": "Not requiring SSL for database connections exposes data in transit to potential interception or man-in-the-middle attacks."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Lock wait logging is disabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "Disabling lock wait logging can make it harder to troubleshoot and identify performance bottlenecks or deadlocks in the database."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = false\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true  # Enabled backups to prevent data loss\n    }\n    ip_configuration {\n      ipv4_enabled    = true\n      require_ssl     = true  # Enforced SSL to secure data in transit\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"  # Enabled lock wait logging for better troubleshooting\n    }\n  }\n}",
  "fix_summary": "Enabled backups to prevent data loss, enforced SSL to secure data in transit, and enabled lock wait logging for better troubleshooting and performance monitoring."
}
